  const car = carFor(q, trade, opts.car || null);
  const tradeProfile = TRADES.find(t => t.id === String(trade || "").toLowerCase());
  const searchContext = !car && tradeProfile && contextWanted(q, String(trade || "").toLowerCase()) ? (tradeProfile.synonyms || []).slice(0, 3).join(" ") : "";
  const place = postcode.locationString(loc);
