/* ============ rate limits ============ */
const buckets = new Map();
let lastSweep = 0;
function sweepBuckets() { const t = now(); if (t - lastSweep < 10 * 60e3) return; lastSweep = t; for (const [k, l] of buckets) if (!l.length || t - l[l.length - 1] > DAY) buckets.delete(k); }
