  if (limited("logo", ip, 120, 60e3)) return bad(res, 429, "rate_limited", "Slow down.");
  let entry = { png: null };
  try {
    const r = await fetch((ENV.LOGO_BASE || "https://www.google.com/s2/favicons?sz=64&domain=") + encodeURIComponent(domain), { signal: AbortSignal.timeout(5000) });
    const type = String(r.headers.get("content-type") || "");
    if (r.ok && /^image\//.test(type)) { const buf = Buffer.from(await r.arrayBuffer()); if (buf.length > 40 && buf.length < 60000) entry = { png: buf, type }; }
  } catch (_) {}
