// A view is counted when the page has actually drawn the ad (the browser reports the ids it showed).
function countAdViews(ids) {
  const day = ukDay(); let n = 0;
  for (const id of [...new Set(ids)].slice(0, 3)) {
    const a = adList().find(x => x.id === id && x.active);
    if (!a) continue;
    a.views = (a.views || 0) + 1; if (a.viewDay !== day) { a.viewDay = day; a.viewsToday = 0; } a.viewsToday = (a.viewsToday || 0) + 1; n++;
  }
  if (n && now() - adViewsSavedAt > 60e3) { adViewsSavedAt = now(); store.save(); }    // saved at most once a minute
}
