      { k: "ka", label: "Breaking", key: true, get: t => { const m = m1(t, /(\d{1,2}(?:\.\d)?)\s?ka\b/); return m ? m[1] + "kA" : null; } },
      { k: "poles", label: "Poles", get: t => { const m = m1(t, /\b(1|2|3|4)\s?p(?:ole)?\b/) || m1(t, /\b(single|double|triple|four)\s?pole\b/); if (!m) return /\b(spn|spsn)\b/.test(t) ? "1P" : /\btpn\b/.test(t) ? "3P" : null; const w = { single: "1", double: "2", triple: "3", four: "4" }; return (w[m[1]] || m[1]) + "P"; } }
