    const pool=mysql.createPool({host,port:Number(process.env.DB_PORT||3306),user:process.env.DB_USER,password:process.env.DB_PASSWORD,database:process.env.DB_NAME,waitForConnections:true,connectionLimit:Number(process.env.DB_POOL_SIZE||5),charset:"utf8mb4"});
