const KNOWN = new Set((LISTS.known || []).map(norm));
const MARKETS = LISTS.marketplaces.map(norm);
const UNRELIABLE = (LISTS.unreliable || []).map(norm);
const TOO_GOOD = 0.7;   // 30%+ below the typical price from a shop you don't know = warn

function classify(store) {
  const n = norm(store);
  const starts = list => list.some(m => n === m || n.startsWith(m + " ") || n.startsWith(m + "-"));
  // private-seller sites you've chosen not to vouch for: always shown as unfamiliar, with the warning
  if (starts(UNRELIABLE)) return "unknown";
  // "eBay - techdeals", "Amazon Marketplace", "OnBuy", "TikTok Shop": anyone can sell there
  if (starts(MARKETS)) return "marketplace";
  if (/\bmarketplace\b|\bseller\b/.test(n)) return "marketplace";
  if (TRUSTED.has(n)) return "trusted";   // the big national suppliers only, by exact name
  // "Screwfix Deals" or "Toolstation Clearance" could be anyone using the name: no Trusted badge, but no warning either
  if ([...TRUSTED].some(m => n.startsWith(m + " ") && !/\b(seller|via)\b/.test(n))) return "known";
  if (KNOWN.has(n)) return "known";       // established shops and brands: no warning, but not "Trusted"
  return "unknown";
}
// The shop's website, for its logo. Known shops by name; otherwise the listing's own link (not Google's).
const DOMAINS = Object.entries(LISTS.domains || {}).map(([k, v]) => [norm(k), v]).sort((a, b) => b[0].length - a[0].length);
function domainOf(store, link) {
  const n = norm(store);
  const hit = DOMAINS.find(([k]) => n === k || n.startsWith(k + " "));
  if (hit) return hit[1];
  try { const h = new URL(link).hostname.replace(/^www\./, ""); if (!/(^|\.)google\.|googleusercontent|gstatic/.test(h)) return h; } catch (_) {}
  return null;
}
