"lib/units.js": function (module, exports, require, __dirname, __filename) {
// Works out pack sizes from listing titles so different drum lengths and pack sizes can be compared fairly.
//   "Prysmian 6242Y 2.5mm Twin & Earth 100m Drum"  -> { metres: 100 }
//   "Wago 221-412 Connectors (Pack of 50)"           -> { count: 50 }
"use strict";

function parseSize(text) {
  const t = String(text || "").toLowerCase().replace(/,/g, "");
  const out = {};
  // lengths: 100m, 100 m, 100 metre(s), 50mtr, 25-metre. Ignore mm/mm² sizes and "m" inside words.
  // the number must stand alone ("100m", "x 100m", "x100m"), not sit inside a part code like "QFS-MX12M"
  const m = t.match(/(?:^|[\s(\/,×]|(?<![a-z0-9])x)(\d{1,4}(?:\.\d+)?)\s?(?:m|mtr|mtrs|metres?|meters?)(?![a-z²0-9])/);
  if (m) out.metres = parseFloat(m[1]);
  // counts: pack of 10, 10 pack, 10pk, box of 100, x10, 10 x, (50)
  // sizes like "600 x 1000", "2400 x 1200mm" or "47x100" are dimensions, never "x 1000" of something
  const tc = t.replace(/\d+(?:\.\d+)?\s?(?:mm|cm|m)?\s?[x×]\s?\d+(?:\.\d+)?(?:\s?(?:mm|cm|m)\b)?(?:\s?[x×]\s?\d+(?:\.\d+)?(?:\s?(?:mm|cm|m)\b)?)?/g, " ");
  const c = tc.match(/(?:pack|box|bag|tub) of (\d{1,4})/) || tc.match(/(\d{1,4})\s?(?:pack|pk|pcs|pieces|piece)\b/) || tc.match(/\bpack\s?\((\d{1,4})\)/) || tc.match(/\bper (\d{1,4})\b/) || tc.match(/\bx\s?(\d{1,4})\b/) || tc.match(/\b(\d{1,4})\s?x\b(?!\s?\d)/);
  if (c) out.count = parseInt(c[1], 10);
  return out;
}

// Price per metre for lengths, per item for packs, otherwise nothing.
function unitPrice(price, title) {
  const s = parseSize(title);
  if (s.metres && s.metres > 1) return { per: "m", value: Math.round(price / s.metres * 1000) / 1000, size: s.metres + "m" };
  if (s.count && s.count > 1) return { per: "each", value: Math.round(price / s.count * 1000) / 1000, size: "pack of " + s.count };
  return null;
}

// True when a listing's size matches the size the tradesperson asked for (or they didn't ask for one).
function sizeMatches(query, title) {
  const want = parseSize(query), got = parseSize(title);
  if (want.metres && got.metres !== want.metres) return false;
  if (want.count && got.count !== want.count) return false;   // a listing that doesn't say its pack size isn't a confirmed match
  return true;
}

// How many of this listing cover the size asked for: 2 x 50m coils for 100m, 2 x 5-packs for a 10-pack.
// Returns null when the listing's size is unknown or it can't be worked out.
function packsNeeded(query, title) {
  const want = parseSize(query), got = parseSize(title);
  if (want.metres && got.metres) return Math.max(1, Math.ceil(want.metres / got.metres - 1e-9));
  if (want.count && got.count) return Math.max(1, Math.ceil(want.count / got.count - 1e-9));
  // No pack size in the title: treat it as sold singly (the safe assumption: it can only over-estimate the cost).
  // (only for sensible numbers: never "1000 radiators" because a pack size was misread)
  if (want.count && !got.count && !got.metres) return want.count <= 50 ? want.count : null;
  return null;
}

module.exports = { parseSize, unitPrice, sizeMatches, packsNeeded };

},
