// ---------- text helpers ----------
const ROMAN = { i: 1, ii: 2, iii: 3, iv: 4, v: 5, vi: 6, vii: 7, viii: 8 };
function clean(s) {
  return " " + String(s || "").toLowerCase()
    .replace(/[ëé]/g, "e")
    .replace(/\bmark\s*(\d)/g, "mk$1").replace(/\bmk\.?\s*(\d)/g, "mk$1")
    .replace(/\bmk\s*(i{1,3}|iv|v|vi{1,3})\b/g, (m, r) => "mk" + ROMAN[r])
    .replace(/[^a-z0-9.+!]+/g, " ").replace(/\s+/g, " ").trim() + " ";
}
// for reading year ranges: keeps the - / > that "2005-2015", "10/2005 - 03/2015" and "2015>" need
const dated = s => " " + String(s || "").toLowerCase().replace(/[^a-z0-9./>-]+/g, " ").replace(/\s+/g, " ").trim() + " ";
const esc = s => String(s).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
// a word or phrase anywhere in the cleaned text, with spaces/hyphens optional between letters and digits ("mx 5" = "mx5")
function phrase(p) {
  const parts = String(p).toLowerCase().replace(/[-\s]+/g, " ").split(" ").map(esc);
  return new RegExp("(?:^| )" + parts.join("[ ]?") + "(?= |$)");
}
const loose = p => phrase(String(p).replace(/([a-z])(\d)/g, "$1 $2").replace(/(\d)([a-z])/g, "$1 $2"));

// ---------- the index ----------
const ALL = [];
for (const mk of MAKES) {
  mk.re = mk.a.map(phrase);
  for (const md of mk.models) {
    md.make = mk;
    const chassis = (md.g || []).flatMap(([codes]) => codes.filter(c => /^(?:[efgr]\d{2}|w\d{3})$/.test(c)));
    const names = [md.n.toLowerCase()].concat(md.a || [], chassis);
    md.re = [...new Set(names)].sort((a, b) => b.length - a.length).map(x => /\d/.test(x) ? loose(x) : phrase(x));
    md.gens = (md.g || []).map(([codes, from, to]) => ({ codes, from, to: to || 2030, label: codes[0].toUpperCase() }));
    ALL.push(md);
  }
}
// longest names first, so "transit custom" wins over "transit" and "range rover sport" over "range rover"
ALL.sort((a, b) => Math.max(...b.re.map(r => r.source.length)) - Math.max(...a.re.map(r => r.source.length)));

function makesIn(t) { return MAKES.filter(m => m.re.some(r => r.test(t))); }
// every model named in the text; m-flagged models count only with their make there too (or "mazda3" written as one word)
function modelsIn(t, makes) {
  const found = [], spans = [];
  for (const md of ALL) {
    const hit = md.re.find(r => r.test(t));
    if (!hit) continue;
    const m = t.match(hit), at = m.index, end = at + m[0].length;
    if (spans.some(([a, b]) => at < b && end > a)) continue;       // inside a longer model already found
    // without the make: "mazda3" written as one word, or with its generation ("polo 6r", "partner b9")
    if (md.m && !makes.includes(md.make) && !/[a-z]{4,}\d/.test(m[0].replace(/ /g, "")) && !md.gens.some(g => g.codes.some(c => c.length > 1 && phrase(c).test(t)))) continue;
    if (md.m && /^ ?\d+ ?$/.test(m[0]) && !new RegExp(md.make.a.map(esc).join("|") + " ?" + esc(m[0].trim())).test(t)) continue;  // "Mazda 3", never a bare "3"
    found.push(md); spans.push([at, end]);
  }
  return found;
}
function gensIn(t, md) {
  const out = [];
  for (const g of md.gens) for (const c of g.codes) {
    const single = /^[a-z]$/.test(c) || /^(?:i|ii|iii|iv|v)$/.test(c);
    // one-letter codes ("Astra H", "Corsa D") only straight after the model name
    const re = single ? new RegExp(md.re.map(r => r.source.replace(/\(\?= \|\$\)$/, "")).join("|").replace(/^/, "(?:") + ") " + esc(c) + "(?= |$)") : phrase(c);
    if (re.test(t)) { out.push(g); break; }
  }
  return out;
}
function yearsIn(t, ctx) {
  const ranges = [];
  const Y = n => { n = Number(n); return n < 100 ? (n > 40 ? 1900 + n : 2000 + n) : n; };
  let x = t;
  // 10/2005 - 03/2015, 2005-2015, 2005 to 2015, 05-15 (two-digit pairs only with a car in the text)
  x = x.replace(/(?:\d{1,2}[./])?((?:19|20)\d{2}) ?(?:-|to|>) ?(?:\d{1,2}[./])?((?:19|20)\d{2})(?![0-9])/g, (m, a, b) => { ranges.push([Y(a), Y(b)]); return " "; });
  x = x.replace(/\b((?:19|20)\d{2}) ?(?:-|>)? ?(?:on|onwards|onward|present|now|>|-)(?= |$)/g, (m, a) => { ranges.push([Y(a), 2030]); return " "; });
  x = x.replace(/\bfrom ((?:19|20)\d{2})\b/g, (m, a) => { ranges.push([Y(a), 2030]); return " "; });
  if (ctx) x = x.replace(/(?:^| |\()(\d{2}) ?- ?(\d{2})(?= |$|\))/g, (m, a, b) => { const A = Y(a), B = Y(b); if (B >= A && B - A <= 25) ranges.push([A, B]); return " "; });
  x = x.replace(/(?:^| )((?:19[89]|20[0-3])\d)(?= |$)/g, (m, a) => { ranges.push([Y(a), Y(a)]); return " "; });
  // "59 plate", "09 reg"
  x.replace(/(?:^| )(\d{2}) ?(?:plate|reg)(?= |$)/g, (m, a) => { const n = Number(a); const y = n >= 50 ? 2000 + n - 50 : 2000 + n; if (y <= 2030) ranges.push([y, y]); return " "; });
  return ranges.filter(([a, b]) => a >= 1960 && b <= 2031 && a <= b);
}
const UNIT_AFTER = /^ ?(?:mm|cm|m|kg|g|kw|w|v|a|ah|mah|bar|psi|nm|inch|in|l|ltr|litre|litres|liter|ml|x|pack|pk|pcs|pc|pair|set|%)(?= |$)/;
function enginesIn(t) {
  const out = [];
  for (const m of t.matchAll(/(?:^| )([0-6]\.\d{1,2})(?= |$|[a-z])/g)) {
    const after = t.slice(m.index + m[0].length);
    if (UNIT_AFTER.test(after) && !/^ ?l (?:petrol|diesel|tdi|tdci|engine|turbo)/.test(after)) continue;   // 2.5mm, 4.5 litre (oil), but "2.0 l diesel" is an engine
    const v = Number(m[1]); if (v >= 0.6 && v <= 6.8) out.push(v);
  }
  for (const m of t.matchAll(/(?:^| )([0-6]\.\d)(?:l|t|d|i|tdi|tdci|tsi|hdi|cdti|dci)(?= |$)/g)) out.push(Number(m[1]));
  return [...new Set(out)];
}
const DIESEL = /(?:^| )(?:diesel|tdi|tdci|cdti|crdi|crdi|hdi|bluehdi|dci|d4d|multijet|jtd|cdi|bluetec|ecoblue|duratorq|skyactiv d|i ctdi)(?= |$)/;
const PETROL = /(?:^| )(?:petrol|tsi|tfsi|fsi|ecoboost|vti|vvti|vvt i|skyactiv g|gti|vtec|i vtec|tce|puretech|t gdi|gdi)(?= |$)/;
function fuelIn(t) { const d = DIESEL.test(t), p = PETROL.test(t); return d && !p ? "diesel" : p && !d ? "petrol" : null; }

