// Undercut on Cloudflare Workers.
// Every request goes to ONE Durable Object ("the app"), which runs the same code as the Node server (server.js)
// and keeps the data in its own storage. One copy means accounts and payments can never be overwritten by
// another copy, and nothing needs a separate database.

let app = null;   // server.js, loaded on the first request inside the Durable Object
async function loadApp(env) {
  if (app) return app;
  // settings from the Cloudflare dashboard (Variables and Secrets) become process.env for the app
  for (const [k, v] of Object.entries(env)) if (typeof v === "string") process.env[k] = v;
  process.env.UNDERCUT_RUNTIME = "cloudflare";
  process.env.DB_DRIVER = "durable";
  if (!process.env.TRUST_PROXY) process.env.TRUST_PROXY = "0";       // the visitor's IP comes from Cloudflare (below)
  if (!process.env.NODE_ENV) process.env.NODE_ENV = "production";
  const mod = __req("server.js");
  app = mod.default || mod;
  return app;
}

// Turns a Cloudflare request into the small part of Node's request/response API that server.js uses.
// Reads a request body but gives up past `limit` bytes, so a huge upload can't fill the app's memory.
async function readCapped(request, limit) {
  if (!request.body) return new Uint8Array(0);
  const reader = request.body.getReader(), parts = []; let size = 0;
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    size += value.byteLength;
    if (size > limit) { try { await reader.cancel(); } catch (_) {} return null; }
    parts.push(value);
  }
  const out = new Uint8Array(size); let at = 0;
  for (const p of parts) { out.set(p, at); at += p.byteLength; }
  return out;
}
const bodyLimit = path => path === "/api/stripe/webhook" ? 512 * 1024 : 64 * 1024;
const tooBig = () => new Response(JSON.stringify({ error: "too_large", message: "That's too much data to send." }), { status: 413, headers: { "content-type": "application/json" } });

async function runNodeStyle(route, request) {
  const url = new URL(request.url);
  let body = new Uint8Array(0);
  if (!["GET", "HEAD"].includes(request.method)) {
    body = await readCapped(request, bodyLimit(url.pathname));
    if (!body) return tooBig();
  }
  const headers = {};
  request.headers.forEach((v, k) => { headers[k.toLowerCase()] = v; });
  const ip = request.headers.get("cf-connecting-ip") || "0.0.0.0";
  const req = {
    method: request.method, url: url.pathname + url.search, headers, socket: { remoteAddress: ip },
    on(ev, fn) {
      if (ev === "data" && body.length) Promise.resolve().then(() => fn(Buffer.from(body)));
      if (ev === "end") Promise.resolve().then(() => Promise.resolve()).then(() => fn());
      return req;
    },
    destroy() {}
  };
  let resolveEnd; const ended = new Promise(r => { resolveEnd = r; });
  const res = {
    statusCode: 200, headersSent: false, req, _h: {},
    setHeader(k, v) { this._h[k] = v; },
    getHeader(k) { return this._h[k]; },
    writeHead(status, h) { this.statusCode = status; Object.assign(this._h, h || {}); this.headersSent = true; return this; },
    end(chunk) { this.headersSent = true; resolveEnd(chunk === undefined ? null : chunk); },
    destroy() { resolveEnd(null); }
  };
  let timer;
  const timeout = new Promise(r => { timer = setTimeout(() => r(undefined), 25000); });
  const chunk = await Promise.race([Promise.resolve(route(req, res)).then(() => ended), timeout]);
  clearTimeout(timer);
  if (chunk === undefined) return new Response(JSON.stringify({ error: "timeout", message: "That took too long. Please try again." }), { status: 504, headers: { "content-type": "application/json" } });
  const out = new Headers();
  for (const [k, v] of Object.entries(res._h)) {
    if (v == null || /^content-length$/i.test(k)) continue;
    if (Array.isArray(v)) v.forEach(x => out.append(k, String(x))); else out.set(k, String(v));
  }
  const noBody = request.method === "HEAD" || [204, 301, 302, 303, 304, 307, 308].includes(res.statusCode);
  return new Response(noBody ? null : chunk, { status: res.statusCode, headers: out });
}

export class UndercutApp extends DurableObject {
  constructor(ctx, env) {
    super(ctx, env);
    this.ready = ctx.blockConcurrencyWhile(async () => {
      const a = await loadApp(env);
      a.store.useDurable(ctx.storage);
      await a.store.init();
    });
  }
  async fetch(request) {
    await this.ready;
    const response = await runNodeStyle(app.route, request);
    // save before replying, so a change is never lost if the app is moved or restarted afterwards
    if (app.store.isDirty()) await app.store.flush();
    return response;
  }
  // called by the cron trigger
  async checkAlerts() {
    await this.ready;
    const result = await app.checkAlerts();
    if (app.store.isDirty()) await app.store.flush();
    return result;
  }
}

// One app, kept in Western Europe near UK users (the hint only matters the first time it's created).
const appStub = env => env.APP.get(env.APP.idFromName("main"), { locationHint: "weur" });

export default {
  fetch(request, env) {
    // refuse oversized uploads here, before they reach the app
    const len = Number(request.headers.get("content-length") || 0);
    if (len > bodyLimit(new URL(request.url).pathname)) return tooBig();
    return appStub(env).fetch(request);
  },
  // Cron (see wrangler.toml): checks price-drop alerts and emails anyone whose price has dropped.
  async scheduled(event, env, ctx) {
    ctx.waitUntil(appStub(env).checkAlerts().then(r => console.log("alerts checked:", JSON.stringify(r))));
  }
};
